source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = []
    blanks = []
    arms = {}
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                if grid[r][c] == 0:
                    blanks.append((r, c))
                    owner = None
                elif grid[r][c] != 3:
                    centers.append((r, c, grid[r][c]))
                    owner = (r, c)
                else:
                    continue
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    arms[(r+dr,c+dc)] = owner
    out = [row[:] for row in grid]
    horizontal = {}
    vertical = {}
    blank_columns = {c for r,c in blanks}
    for r, c, color in centers:
        for dr, dc, plane in [(0,-1,'h'),(0,1,'h'),(-1,0,'v'),(1,0,'v')]:
            rr, cc = r+dr, c+dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 3:
                    if arms.get((rr,cc)) != (r,c):
                        break
                elif grid[rr][cc] != 0:
                    break
                if plane == 'h':
                    if cc not in blank_columns and grid[rr][cc] == 0:
                        horizontal[(rr,cc)] = color
                elif grid[rr][cc] == 0:
                    vertical[(rr,cc)] = color
                rr += dr
                cc += dc
    for cell, color in horizontal.items():
        r,c=cell
        if grid[r][c] == 0:
            out[r][c]=color
    for cell, color in vertical.items():
        r,c=cell
        if grid[r][c] == 0:
            out[r][c]=color
    return out
